/**
 * The device shell (SRS §7). Every command line, typed or generated by a click, runs here; the
 * command and each output line are appended to the simulator's trace (`cmd.exec`, `proc.output`),
 * which is where the console reads them from (SIM-38).
 */
import type { CmdSource, DeviceId, Simulator } from "@wirelight/sim";
import { clear, exit, help, history, man } from "./commands/builtins";
import { ip } from "./commands/ip";
import { lab } from "./commands/lab";
import { tokenize } from "./tokenize";
import type { CommandContext, CommandFn, ShellContent, ToolId } from "./types";

const BUILTINS: Record<string, CommandFn> = { help, man, history, clear, exit };
const PROGRAMS: Record<string, CommandFn> = { ip, lab };
/** Real Linux programs the player meets later; until unlocked they answer FR-CON-11. */
const LATER = new Set([
  "bridge",
  "ping",
  "tcpdump",
  "sysctl",
  "dhclient",
  "traceroute",
  "ssh",
  "ss",
  "nc",
  "dig",
  "curl",
  "iptables",
]);

export interface ExecOptions {
  tools: ReadonlySet<ToolId>;
  subtitles: boolean;
}

type Chunk = { stream: "stdout" | "stderr" | "note" | "control"; text: string };

export class Shell {
  private nextExecId = 1;
  private readonly histories = new Map<DeviceId, string[]>();
  readonly flags = { labNoteShown: false, sudoNoteShown: false };

  constructor(private readonly content: ShellContent) {}

  history(device: DeviceId): readonly string[] {
    return this.histories.get(device) ?? [];
  }

  exec(
    sim: Simulator,
    device: DeviceId,
    line: string,
    source: CmdSource,
    opts: ExecOptions,
  ): { execId: number; exitCode: number } {
    const execId = this.nextExecId++;
    const trimmed = line.trim();
    if (source === "typed" || source === "click") {
      const h = this.histories.get(device) ?? [];
      if (trimmed && h.at(-1) !== trimmed) h.push(trimmed);
      this.histories.set(device, h);
    }

    const chunks: Chunk[] = [];
    const exitCode = this.run(sim, device, trimmed, opts, chunks);

    sim.emit({ kind: "cmd.exec", t: sim.now, device, execId, line: trimmed, source, exitCode });
    for (const c of chunks) {
      sim.emit({ kind: "proc.output", t: sim.now, device, execId, text: c.text, stream: c.stream });
    }
    return { execId, exitCode };
  }

  private run(sim: Simulator, device: DeviceId, line: string, opts: ExecOptions, chunks: Chunk[]): number {
    const tok = tokenize(line);
    if (!tok.ok) {
      chunks.push({ stream: "stderr", text: tok.error });
      return 2;
    }
    const [first = [], ...pipes] = tok.stages;
    if (first.length === 0) return 0;

    let words = first;
    if (words[0] === "sudo") {
      if (!this.flags.sudoNoteShown) {
        chunks.push({ stream: "note", text: this.content.notes.sudo });
        this.flags.sudoNoteShown = true;
      }
      words = words.slice(1);
      if (words.length === 0) {
        chunks.push({ stream: "stderr", text: "usage: sudo command" });
        return 1;
      }
    }

    // Output keeps the order it was written in; `| grep` filters stdout only, as stderr isn't piped.
    let buf: Chunk[] = [];
    const ctx: CommandContext = {
      sim,
      device,
      tools: opts.tools,
      content: this.content,
      history: this.history(device),
      flags: this.flags,
      out: (text) => buf.push({ stream: "stdout", text }),
      err: (text) => {
        buf.push({ stream: "stderr", text });
        const sub = opts.subtitles ? this.content.subtitle(text) : undefined;
        if (sub) buf.push({ stream: "note", text: sub });
      },
      note: (text) => buf.push({ stream: "note", text }),
      control: (action) => buf.push({ stream: "control", text: action }),
    };

    const [name = "", ...args] = words;
    const fn = BUILTINS[name] ?? PROGRAMS[name];
    let code: number;
    if (fn) code = fn(ctx, args);
    else if (LATER.has(name)) {
      ctx.note(this.content.notes.locked);
      code = 127;
    } else {
      ctx.err(`${name}: command not found`);
      code = 127;
    }

    for (const stage of pipes) {
      const [cmd, ...gargs] = stage;
      const stdout = buf.filter((c) => c.stream === "stdout").map((c) => c.text);
      const rest = buf.filter((c) => c.stream !== "stdout");
      if (cmd !== "grep") {
        buf = [...rest, { stream: "stderr", text: `${cmd ?? ""}: command not found` }];
        code = 127;
        continue;
      }
      const g = grep(gargs, stdout);
      if (!g.ok) {
        buf = [...rest, ...g.error.split("\n").map((text) => ({ stream: "stderr" as const, text }))];
        code = 2;
        continue;
      }
      const keep = new Set(g.lines);
      buf = buf.filter((c) => c.stream !== "stdout" || keep.has(c.text));
      code = g.lines.length > 0 ? 0 : 1;
    }

    chunks.push(...buf);
    return code;
  }
}

function grep(args: string[], lines: string[]): { ok: true; lines: string[] } | { ok: false; error: string } {
  let ignoreCase = false;
  let invert = false;
  let pattern: string | undefined;
  for (const a of args) {
    if (pattern === undefined && /^-[iv]+$/.test(a)) {
      if (a.includes("i")) ignoreCase = true;
      if (a.includes("v")) invert = true;
    } else if (pattern === undefined) {
      pattern = a;
    } else {
      return { ok: false, error: `grep: ${a}: No such file or directory` };
    }
  }
  if (pattern === undefined) {
    return { ok: false, error: "Usage: grep [OPTION]... PATTERNS [FILE]...\nTry 'grep --help' for more information." };
  }
  let re: RegExp;
  try {
    // grep's default syntax is basic regular expressions; for the patterns players type, JS regex agrees.
    re = new RegExp(pattern, ignoreCase ? "i" : "");
  } catch {
    return { ok: false, error: "grep: Unmatched ( or \\(" };
  }
  return { ok: true, lines: lines.filter((l) => re.test(l) !== invert) };
}
